import React from 'react';

const About = () => {
    return (
        <div className="about">
            <h1>About Me</h1>
            <p>Hello! I'm [Your Name], a passionate developer with a love for creating web applications.</p>
            <h2>Personal Background</h2>
            <p>I grew up in [Your Hometown] and have always been interested in technology and design.</p>
            <h2>Hobbies & Interests</h2>
            <ul>
                <li>Coding</li>
                <li>Reading</li>
                <li>Traveling</li>
                <li>Photography</li>
            </ul>
        </div>
    );
};

export default About;
